// Differential tests: run each compiled corpus in the TS VM and compare its
// print output byte-for-byte against the golden captured from native z8lua.
//
// Goldens + compiled dumps are generated by `npm run diff:gen` (requires WSL);
// the test itself is hermetic.
import { existsSync, readFileSync, readdirSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { ROOT, readLatin1, runVm } from "./helpers.ts";

const CORPUS = join(ROOT, "tests", "differential", "corpus");
const COMPILED = join(ROOT, "tests", "differential", "compiled");
const GOLDEN = join(ROOT, "tests", "differential", "golden");

function firstDiff(a: string, b: string): string {
  const n = Math.min(a.length, b.length);
  for (let i = 0; i < n; i++) {
    if (a.charCodeAt(i) !== b.charCodeAt(i)) {
      const ctx = 60;
      const from = Math.max(0, i - ctx);
      return (
        `byte ${i} (0x${a.charCodeAt(i).toString(16)} vs ` +
        `0x${b.charCodeAt(i).toString(16)})\n` +
        `  vm  : ${JSON.stringify(a.slice(from, i + ctx))}\n` +
        `  gold: ${JSON.stringify(b.slice(from, i + ctx))}`
      );
    }
  }
  return (
    `length ${a.length} vs ${b.length}\n` +
    `  vm  tail : ${JSON.stringify(a.slice(n, n + 80))}\n` +
    `  gold tail: ${JSON.stringify(b.slice(n, n + 80))}`
  );
}

const corpusFiles = existsSync(CORPUS)
  ? readdirSync(CORPUS).filter((f) => f.endsWith(".lua")).sort()
  : [];

describe("differential vs native z8lua", () => {
  it("has corpus files", () => {
    expect(corpusFiles.length).toBeGreaterThan(0);
  });

  it("loads and executes assets/bios.bc matching its golden", () => {
    const bcPath = join(ROOT, "assets", "bios.bc");
    const goldPath = join(GOLDEN, "bios.out");
    if (!existsSync(bcPath) || !existsSync(goldPath)) {
      throw new Error(
        "missing bios.bc / golden/bios.out — run: extract-bios + diff:gen",
      );
    }
    const run = runVm(new Uint8Array(readFileSync(bcPath)), "@bios.bc");
    if (run.error) {
      throw new Error(
        `bios.bc raised an uncaught error:\n${run.errorText ?? run.error.message}`,
      );
    }
    expect(run.output).toBe(readLatin1(goldPath));
  });

  for (const f of corpusFiles) {
    const base = f.replace(/\.lua$/, "");
    it(
      `runs ${base} identically to native z8lua`,
      { timeout: 60_000 },
      () => {
        const bcPath = join(COMPILED, `${base}.bc`);
        const goldPath = join(GOLDEN, `${base}.out`);
        if (!existsSync(bcPath) || !existsSync(goldPath)) {
          throw new Error(
            `missing artifacts for ${base} — run: npm run diff:gen`,
          );
        }
        const bc = readFileSync(bcPath);
        const gold = readLatin1(goldPath);
        const chunkname = `@tests/differential/corpus/${f}`;
        const run = runVm(bc, chunkname);
        if (run.error) {
          throw new Error(
            `VM raised an uncaught error:\n${run.errorText ?? run.error.message}`,
          );
        }
        if (run.output !== gold) {
          throw new Error(
            `output mismatch for ${base}:\n${firstDiff(run.output, gold)}`,
          );
        }
        expect(run.output).toBe(gold);
      },
    );
  }
});
